using System.Text.RegularExpressions;using System.Text.Json;using System.Security.Cryptography;using System.Text;
namespace GameTranslator.Translation;
public static class EngineComparison {
 public sealed record Entry(string Game,string Engine,string Source,string Arabic,int TotalMs,int TranslationMs,int Rating=0);
 public static string Engine(string label){var n=label.ToLowerInvariant();if(n.Contains("ذاكرة")||n.Contains("تصحيح")||n.Contains("حزمة"))return "";return n.Contains("quickmt")?"QuickMT":n.Contains("deepl")?"DeepL":"";}
 private static string SourceKey(string text)=>Regex.Replace(Regex.Replace(text.ToLowerInvariant().Replace("’","").Replace("'",""),@"[^a-z0-9\s]"," "),@"\s+"," ").Trim();
 private static string GameKey(string text){var n=text.Trim().ToLowerInvariant();return n is "gta6" or "gta 6" or "gta vi" or "grand theft auto 6" or "grand theft auto vi"?"gta6":DialogueProfile.Rdr2(text)?"rdr2":n;}
 public static string Summary(IEnumerable<Entry> rows){var matched=rows.Where(r=>r.TranslationMs>0&&Engine(r.Engine)!="").GroupBy(r=>GameKey(r.Game)+"\n"+SourceKey(r.Source)).Select(g=>g.GroupBy(r=>Engine(r.Engine)).ToDictionary(p=>p.Key,p=>p.Last())).Where(g=>g.ContainsKey("QuickMT")&&g.ContainsKey("DeepL")).ToArray();if(matched.Length==0)return "لا توجد جمل مشتركة بين QuickMT وDeepL. أعد الحوار نفسه بالمحركين مع تفعيل السجل ثم قيّم النتائج. نستبعد الذاكرة والحزم؛ لا تُرسل طلبات إضافية للمقارنة أثناء اللعب.";return "جمل مشتركة: "+matched.Length+" — نفس اللعبة والنص.\n"+Stats("QuickMT",matched.Select(g=>g["QuickMT"]).ToArray())+"\n"+Stats("DeepL",matched.Select(g=>g["DeepL"]).ToArray())+"\nالدقة حسب تقييمك، وغير المقيّم لا يُحسب صحيحًا. الزمن داخل التطبيق ولا يشمل البث أو التلفزيون. قد يشمل زمن ويندوز ذاكرة داخلية للمحرك لا يميزها السجل؛ أعد جلسة جديدة للمقارنة. لا نختار المحرك تلقائيًا من عينة صغيرة.";}
 private static string Stats(string name,Entry[] rows){var ms=rows.Select(r=>r.TotalMs).Order().ToArray();double median=ms.Length%2==1?ms[ms.Length/2]:(ms[ms.Length/2-1]+ms[ms.Length/2])/2.0;return $"{name}: وسيط التجهيز {median} ms؛ صحيح {rows.Count(r=>r.Rating==1)} / خطأ {rows.Count(r=>r.Rating==-1)} / غير مقيّم {rows.Count(r=>r.Rating==0)}";}
 private static readonly string RatingsFile=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ArabicGames","Quality","comparison-ratings.json");
 private static string RatingKey(Entry row)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(GameKey(row.Game)+"\n"+row.Engine+"\n"+row.Source+"\n"+row.Arabic)));
 private static Dictionary<string,int> Ratings(){try{return File.Exists(RatingsFile)&&new FileInfo(RatingsFile).Length<1_000_000?JsonSerializer.Deserialize<Dictionary<string,int>>(File.ReadAllText(RatingsFile))??[]:[];}catch{return [];}}
 public static int Rating(Entry row)=>Ratings().GetValueOrDefault(RatingKey(row));
 public static void Rate(Entry row,int rating){if(rating is not (-1 or 1))throw new ArgumentException();var saved=Ratings();if(saved.Count>=5000&&!saved.ContainsKey(RatingKey(row)))throw new InvalidOperationException("Rating store full");saved[RatingKey(row)]=rating;Directory.CreateDirectory(Path.GetDirectoryName(RatingsFile)!);File.WriteAllText(RatingsFile+".tmp",JsonSerializer.Serialize(saved));File.Move(RatingsFile+".tmp",RatingsFile,true);}
}
